<script setup lang="ts">
import { computed } from "vue";
import { Head, Link } from "@inertiajs/vue3";
import { ArrowLeft, ArrowUpRight, BriefcaseBusiness, CheckCircle2, ClockAlert, ListChecks, Users, CalendarDays } from "@lucide/vue";
import AppLayout from "@/Layouts/AppLayout.vue";
const props = defineProps<{ employee: any; periodLabel: string; jobs: any[]; tasks: any[]; attendance: any[] }>();
const e = props.employee;
const completionRate = computed(() => e.completed + e.processing ? Math.round(e.completed / (e.completed + e.processing) * 100) + "%" : "—");
const punctualRate = computed(() => e.workingDays !== null && e.presentDays ? Math.round(Math.max(0, e.presentDays - e.lateDays) / e.presentDays * 100) + "%" : "—");
const cards = computed(() => [
    { label: "Berkas PIC", value: e.totalJobs, note: "Seluruh status", icon: BriefcaseBusiness, color: "text-blue-700 bg-blue-50" },
    { label: "Berkas selesai", value: e.completed, note: "Status saat ini selesai", icon: CheckCircle2, color: "text-emerald-700 bg-emerald-50" },
    { label: "Berkas aktif", value: e.processing, note: `${e.overdue} melewati deadline`, icon: ClockAlert, color: "text-amber-700 bg-amber-50" },
    { label: "Tingkat penyelesaian", value: completionRate.value, note: "Selesai / (selesai + aktif)", icon: ListChecks, color: "text-violet-700 bg-violet-50" },
    { label: "Total tugas", value: e.totalTasks, note: `${e.picTasks} PIC · ${e.witnessTasks} saksi`, icon: Users, color: "text-slate-700 bg-slate-100" },
    { label: "Hadir", value: e.workingDays === null ? "—" : e.presentDays, note: `Hari dengan check-in · ${props.periodLabel}`, icon: CalendarDays, color: "text-teal-700 bg-teal-50" },
    { label: "Terlambat", value: e.workingDays === null ? "—" : e.lateDays, note: "Hari check-in setelah 08.00", icon: ClockAlert, color: "text-orange-700 bg-orange-50" },
    { label: "Tepat waktu", value: punctualRate.value, note: "Hari hadir tidak terlambat / hadir", icon: CheckCircle2, color: "text-emerald-700 bg-emerald-50" },
]);
const date = (v?: string | null) => v ? new Date(String(v).slice(0, 10) + "T00:00:00").toLocaleDateString("id-ID", { day: "numeric", month: "short", year: "numeric" }) : "—";
const time = (v?: string | null) => v ? String(v).includes(" ") ? String(v).split(" ")[1].slice(0, 5) : String(v).slice(0, 5) : "—";
</script>
<template>
<Head :title="`KPI ${employee.fullName || employee.username}`" /><AppLayout><main class="mx-auto max-w-7xl space-y-6 p-4">
    <Link href="/dashboard/productivity" class="inline-flex items-center gap-2 text-sm font-bold text-slate-500 hover:text-[var(--primary)]"><ArrowLeft class="h-4 w-4" /> Kembali ke produktivitas</Link>
    <header class="flex flex-wrap justify-between gap-3"><div><p class="text-xs font-black uppercase tracking-[.18em] text-[var(--primary)]">Detail KPI pegawai</p><h1 class="mt-1 text-2xl font-black sm:text-3xl">{{ employee.fullName || employee.username }}</h1><p class="mt-1 text-sm text-slate-500">{{ employee.role }} · {{ employee.username }}</p></div><Link :href="`/dashboard/pegawai/${encodeURIComponent(employee.id)}`" class="self-start rounded-xl border border-slate-200 bg-white px-4 py-2 text-sm font-bold">Data pegawai</Link></header>
    <p class="text-sm text-slate-500">Berkas dan tugas dihitung sepanjang waktu. Absensi dihitung untuk {{ periodLabel }}.</p>
    <section class="grid grid-cols-2 gap-3 lg:grid-cols-4"><article v-for="card in cards" :key="card.label" class="rounded-2xl border border-slate-200 bg-white p-4 shadow-sm"><div class="flex justify-between gap-2"><p class="text-[10px] font-black uppercase tracking-wide text-slate-500">{{ card.label }}</p><span class="rounded-lg p-2" :class="card.color"><component :is="card.icon" class="h-4 w-4" /></span></div><p class="mt-2 text-3xl font-black">{{ card.value }}</p><p class="mt-2 text-xs text-slate-500">{{ card.note }}</p></article></section>
    <section class="grid gap-4 lg:grid-cols-2"><article class="rounded-2xl border border-slate-200 bg-white p-5"><h2 class="font-black">Komposisi pekerjaan PIC</h2><p class="mt-1 text-xs text-slate-500">Status berkas saat ini; dibatalkan tidak dihitung dalam tingkat penyelesaian.</p><div class="mt-4 grid grid-cols-3 gap-2 text-center"><div v-for="item in [{label:'Selesai',value:e.completed},{label:'Aktif',value:e.processing},{label:'Dibatalkan',value:e.cancelled}]" :key="item.label" class="rounded-xl bg-slate-50 p-3"><p class="text-xl font-black">{{ item.value }}</p><p class="text-xs text-slate-500">{{ item.label }}</p></div></div></article>
    <article class="rounded-2xl border border-slate-200 bg-white p-5"><h2 class="font-black">Kehadiran {{ periodLabel }}</h2><p class="mt-1 text-xs text-slate-500">Perkiraan berdasarkan hari Senin–Jumat sejak profil pegawai dibuat, termasuk hari ini.</p><div v-if="e.workingDays !== null" class="mt-4 grid grid-cols-3 gap-2 text-center"><div v-for="item in [{label:'Hari kerja',value:e.workingDays},{label:'Hadir',value:e.presentDays},{label:'Belum ada absensi',value:e.absentDays}]" :key="item.label" class="rounded-xl bg-slate-50 p-3"><p class="text-xl font-black">{{ item.value }}</p><p class="text-xs text-slate-500">{{ item.label }}</p></div></div><p v-else class="mt-4 text-sm text-slate-500">Profil absensi belum tersedia.</p><p class="mt-3 text-xs text-slate-500">Belum ada absensi bukan konfirmasi mangkir; libur, cuti, jadwal khusus, dan tanggal masuk kerja belum diperhitungkan.</p></article></section>
    <section class="rounded-2xl border border-slate-200 bg-white p-5"><div class="flex justify-between"><div><h2 class="font-black">Berkas PIC terbaru</h2><p class="text-xs text-slate-500">Maksimal 10 berkas, diurutkan berdasarkan tanggal dibuat.</p></div></div><div v-if="jobs.length" class="mt-4 divide-y divide-slate-100"><Link v-for="job in jobs" :key="job.jobType + job.id" :href="`/dashboard/jobs/${job.jobType}/${job.id}`" class="flex items-center justify-between gap-4 py-3 hover:text-[var(--primary)]"><div class="min-w-0"><p class="font-bold">{{ job.title }}</p><p class="text-xs text-slate-500">{{ job.trackingCode || '—' }} · {{ job.category }} · Deadline {{ date(job.deadline) }}</p></div><span class="shrink-0 text-xs font-bold">{{ job.status }} <ArrowUpRight class="inline h-4 w-4" /></span></Link></div><p v-else class="mt-4 text-sm text-slate-500">Belum ada berkas sebagai PIC.</p></section>
    <div class="grid gap-4 lg:grid-cols-2"><section class="rounded-2xl border border-slate-200 bg-white p-5"><h2 class="font-black">Tugas terbaru</h2><p class="mt-1 text-xs text-slate-500">Maksimal 10 penugasan terbaru.</p><div v-if="tasks.length" class="mt-3 divide-y divide-slate-100"><div v-for="task in tasks" :key="task.id" class="py-3"><p class="text-sm font-bold">{{ task.customTask || task.taskType }} <span class="font-normal text-slate-500">· {{ date(task.createdAt) }}</span></p><p class="text-xs text-slate-500">{{ task.jobTitle || 'Berkas tidak tersedia' }}</p></div></div><p v-else class="mt-4 text-sm text-slate-500">Belum ada tugas.</p></section>
    <section class="rounded-2xl border border-slate-200 bg-white p-5"><h2 class="font-black">Riwayat absensi</h2><p class="mt-1 text-xs text-slate-500">Catatan untuk {{ periodLabel }}.</p><div v-if="attendance.length" class="mt-3 max-h-80 overflow-auto divide-y divide-slate-100"><div v-for="(record, i) in attendance" :key="i" class="flex justify-between gap-3 py-3 text-sm"><span class="font-bold">{{ date(record.date) }}</span><span class="text-slate-500">Masuk {{ time(record.checkIn) }} · Pulang {{ time(record.checkOut) }}</span></div></div><p v-else class="mt-4 text-sm text-slate-500">Belum ada catatan absensi periode ini.</p></section></div>
</main></AppLayout>
</template>
